function makeResult(overrides = {}) {
  return {
    status: 'success',
    created: 0,
    updated: 0,
    deleted: 0,
    warnings: [],
    errors: [],
    summary: {},
    ...overrides
  };
}

async function syncMenus({ config, client }) {
  const result = makeResult();
  const sourceMenus = await client.source.menus.listAll();
  const destinationMenus = await client.destination.menus.listAll();
  const destinationByHandle = new Map(
    destinationMenus.map((menu) => [menu.handle, menu])
  );

  for (const sourceMenu of sourceMenus) {
    const destinationMenu = destinationByHandle.get(sourceMenu.handle);

    try {
      if (destinationMenu) {
        if (!config.createOnly) {
          await client.destination.menus.update(destinationMenu.id, sourceMenu);
          result.updated += 1;
        }
      } else if (!config.updateOnly) {
        const created = await client.destination.menus.create(sourceMenu);
        if (created) {
          result.created += 1;
        }
      }
    } catch (error) {
      result.errors.push(`Error processing "${sourceMenu.title}": ${error.message}`);
    }
  }

  if (config.cleanDestination && !config.createOnly && !config.updateOnly) {
    const sourceHandles = new Set(sourceMenus.map((menu) => menu.handle));

    for (const destinationMenu of destinationMenus) {
      if (sourceHandles.has(destinationMenu.handle)) {
        continue;
      }

      try {
        await client.destination.menus.delete(destinationMenu.id);
        result.deleted += 1;
      } catch (error) {
        result.errors.push(`Error deleting "${destinationMenu.title}": ${error.message}`);
      }
    }
  }

  result.status = result.errors.length > 0 ? 'failed' : 'success';
  result.summary = {
    sourceCount: sourceMenus.length,
    destinationCount: destinationMenus.length
  };

  return result;
}

module.exports = {
  syncMenus
};
